<?php
/**  * Security Reports - Standalone Page  * Login Attempts, Access Violations, Password Resets, Suspicious Activity  */  require_once __DIR__ . '/../backend/lib.php';
require_once __DIR__ . '/../public/db_connect.php';
require_login();  $u = current_user();
$role = $u['role'] ?? 'staff';
$roleKey = function_exists('role_key') ? role_key($role) : strtolower(trim((string)$role));  if (!in_array($roleKey, ['superadmin', 'developer'], true)) {  header('Location: dashboard.php');  exit;
}  $page_id = 'superadmin_reports';
$station_name = '';  // Ensure tables exist
try {  $pdo->exec("  CREATE TABLE IF NOT EXISTS login_attempts_security (  id INT AUTO_INCREMENT PRIMARY KEY,  username VARCHAR(100) NOT NULL,  attempt_type VARCHAR(20) NOT NULL COMMENT 'success, failed',  ip_address VARCHAR(45),  user_agent TEXT,  failure_reason VARCHAR(255),  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,  INDEX idx_username (username),  INDEX idx_attempt_type (attempt_type),  INDEX idx_created_at (created_at)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4  ");  $pdo->exec("  CREATE TABLE IF NOT EXISTS access_violations_log (  id INT AUTO_INCREMENT PRIMARY KEY,  user_id INT,  username VARCHAR(100),  attempted_resource VARCHAR(255),  violation_type VARCHAR(100) COMMENT 'unauthorized_page, privilege_escalation, forbidden_api',  ip_address VARCHAR(45),  user_agent TEXT,  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,  INDEX idx_user_id (user_id),  INDEX idx_violation_type (violation_type)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4  ");  $pdo->exec("  CREATE TABLE IF NOT EXISTS password_reset_logs (  id INT AUTO_INCREMENT PRIMARY KEY,  user_id INT NOT NULL,  username VARCHAR(100),  reset_method VARCHAR(50) COMMENT 'email, admin, security_question',  ip_address VARCHAR(45),  status VARCHAR(20) DEFAULT 'pending',  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,  completed_at DATETIME NULL,  INDEX idx_user_id (user_id),  INDEX idx_created_at (created_at)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4  ");  $pdo->exec("  CREATE TABLE IF NOT EXISTS suspicious_activity_alerts (  id INT AUTO_INCREMENT PRIMARY KEY,  user_id INT,  username VARCHAR(100),  activity_type VARCHAR(100) COMMENT 'multiple_failed_logins, unusual_access_pattern, data_exfiltration',  severity VARCHAR(20) DEFAULT 'medium',  description TEXT,  ip_address VARCHAR(45),  status VARCHAR(20) DEFAULT 'open',  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,  INDEX idx_severity (severity),  INDEX idx_status (status)  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4  ");
} catch (Exception $e) {  error_log("Security Reports table creation: " . $e->getMessage());
}  // Filters
$date_from = $_GET['date_from'] ?? date('Y-m-d', strtotime('-30 days'));
$date_to  = $_GET['date_to']  ?? date('Y-m-d');  // ── Login Attempts (real: login_attempts — 40 rows) ───────────
$stmt_logins = $pdo->prepare("  SELECT username, status AS attempt_type,  COUNT(*) as attempt_count,  ip_address,  MAX(attempt_time) as last_attempt,  GROUP_CONCAT(DISTINCT failure_reason SEPARATOR '; ') AS failure_reasons  FROM login_attempts  WHERE attempt_time BETWEEN ? AND ?  GROUP BY username, status, ip_address  ORDER BY last_attempt DESC  LIMIT 200
");
$stmt_logins->execute([$date_from.' 00:00:00', $date_to.' 23:59:59']);
$login_attempts = $stmt_logins->fetchAll(PDO::FETCH_ASSOC);  // Summary stats from login_attempts
$stmt_login_stats = $pdo->prepare("  SELECT status AS attempt_type, COUNT(*) as count  FROM login_attempts  WHERE attempt_time BETWEEN ? AND ?  GROUP BY status
");
$stmt_login_stats->execute([$date_from.' 00:00:00', $date_to.' 23:59:59']);
$login_stats = [];
foreach ($stmt_login_stats->fetchAll(PDO::FETCH_ASSOC) as $stat) {  $login_stats[$stat['attempt_type']] = $stat['count'];
}
$sec_total_logins  = array_sum($login_stats);
$sec_failed_logins = ($login_stats['failed'] ?? 0) + ($login_stats['fail'] ?? 0);
$sec_success_logins = $login_stats['success'] ?? 0;  // ── Access Violations (real: access_violations_log, fallback: audit_logs) ──
$stmt_violations = $pdo->prepare("  SELECT * FROM access_violations_log  WHERE created_at BETWEEN ? AND ?  ORDER BY created_at DESC LIMIT 100
");
$stmt_violations->execute([$date_from.' 00:00:00', $date_to.' 23:59:59']);
$access_violations = $stmt_violations->fetchAll(PDO::FETCH_ASSOC);  if (empty($access_violations)) {  // Fallback: look for 'Access Denied', 'Unauthorized' in audit_logs  $stmt_viol_fb = $pdo->prepare("  SELECT id,  user_id,  COALESCE(  (SELECT username FROM users WHERE id = audit_logs.user_id LIMIT 1),  'Unknown'  ) AS username,  action_details AS attempted_resource,  action_type  AS violation_type,  ip_address,  user_agent,  created_at  FROM audit_logs  WHERE (action_type LIKE '%denied%' OR action_type LIKE '%unauthorized%'  OR action_type LIKE '%Failed%' OR action_type LIKE '%blocked%')  AND created_at BETWEEN ? AND ?  ORDER BY created_at DESC LIMIT 100  ");  $stmt_viol_fb->execute([$date_from.' 00:00:00', $date_to.' 23:59:59']);  $access_violations = $stmt_viol_fb->fetchAll(PDO::FETCH_ASSOC);
}  // ── Password Reset Logs (real: password_reset_logs or password_reset_tokens) ──
$stmt_resets = $pdo->prepare("  SELECT * FROM password_reset_logs  WHERE created_at BETWEEN ? AND ?  ORDER BY created_at DESC LIMIT 100
");
$stmt_resets->execute([$date_from.' 00:00:00', $date_to.' 23:59:59']);
$password_resets = $stmt_resets->fetchAll(PDO::FETCH_ASSOC);  if (empty($password_resets)) {  // Fallback: password_reset_tokens table  try {  $cols = $pdo->query("SHOW COLUMNS FROM password_reset_tokens")->fetchAll(PDO::FETCH_COLUMN);  if (in_array('created_at', $cols)) {  $stmt_rst_fb = $pdo->prepare("  SELECT id, user_id,  COALESCE(  (SELECT username FROM users WHERE id = password_reset_tokens.user_id LIMIT 1),  'Unknown'  ) AS username,  'email' AS reset_method,  NULL AS ip_address,  'completed' AS status,  created_at,  NULL AS completed_at  FROM password_reset_tokens  WHERE created_at BETWEEN ? AND ?  ORDER BY created_at DESC LIMIT 100  ");  $stmt_rst_fb->execute([$date_from.' 00:00:00', $date_to.' 23:59:59']);  $password_resets = $stmt_rst_fb->fetchAll(PDO::FETCH_ASSOC);  }  } catch (Exception $e) {}
}  // ── Suspicious Activity (real: suspicious_activity_alerts, fallback: audit_logs CAPTCHA fail) ──
$stmt_suspicious = $pdo->prepare("  SELECT * FROM suspicious_activity_alerts  WHERE created_at BETWEEN ? AND ?  ORDER BY severity DESC, created_at DESC LIMIT 100
");
$stmt_suspicious->execute([$date_from.' 00:00:00', $date_to.' 23:59:59']);
$suspicious_activity = $stmt_suspicious->fetchAll(PDO::FETCH_ASSOC);  if (empty($suspicious_activity)) {  // Fallback: multiple failed logins from login_attempts grouped by IP  $stmt_susp_fb = $pdo->prepare("  SELECT ip_address,  GROUP_CONCAT(DISTINCT username ORDER BY attempt_time DESC SEPARATOR ', ') AS username,  COUNT(*) AS fail_count,  MAX(attempt_time) AS created_at,  'multiple_failed_logins' AS activity_type,  CASE WHEN COUNT(*) >= 10 THEN 'high'  WHEN COUNT(*) >= 5  THEN 'medium'  ELSE 'low' END AS severity,  CONCAT(COUNT(*), ' failed login attempt(s) from this IP') AS description,  'open' AS status  FROM login_attempts  WHERE status = 'failed'  AND attempt_time BETWEEN ? AND ?  GROUP BY ip_address  HAVING COUNT(*) >= 2  ORDER BY fail_count DESC LIMIT 50  ");  $stmt_susp_fb->execute([$date_from.' 00:00:00', $date_to.' 23:59:59']);  $suspicious_activity = $stmt_susp_fb->fetchAll(PDO::FETCH_ASSOC);
}  include __DIR__ . '/../partials/header.php';
?>  <style>
