 4px 0 !important;  margin-bottom: 8px !important;  }  /* Cards */  .report-card {  page-break-inside: auto !important;  break-inside: auto !important;  margin-bottom: 12px !important;  border: 1px solid #b0bec8 !important;  box-shadow: none !important;  width: 100% !important;  overflow: visible !important;  }  .report-card-header {  background: #eef2f8 !important;  padding: 6px 10px !important;  border-bottom: 1px solid #b0bec8 !important;  }  .report-card-header h3,  .report-card-title {  font-size: 11px !important;  font-weight: 700 !important;  color: #003366 !important;  margin: 0 !important;  text-transform: uppercase !important;  letter-spacing: 0.5px !important;  }  .report-card-body {  padding: 10px 12px !important;  overflow: visible !important;  height: auto !important;  }  /* Kill overflow wrappers around tables in print */  div[style*="overflow-x"],  .report-card-body > div {  overflow: visible !important;  overflow-x: visible !important;  width: 100% !important;  max-width: 100% !important;  }  /* Tables — Landscape Optimized, Auto Width Distribution */  .data-table {  width: 100% !important;  border-collapse: collapse !important;  font-size: 8px !important;  page-break-inside: auto !important;  table-layout: auto !important;  word-break: break-all !important;  overflow-wrap: anywhere !important;  }  .data-table thead { display: table-header-group !important; }  .data-table tbody { display: table-row-group !important; }  .data-table thead tr {  background: #00264D !important;  }  .data-table thead th {  padding: 6px 5px !important;  font-size: 7.5px !important;  font-weight: 700 !important;  text-transform: uppercase !important;  letter-spacing: 0.3px !important;  border: 1px solid #00264D !important;  text-align: center !important;  color: white !important;  background: #00264D !important;  white-space: normal !important;  }  .data-table tbody td {  padding: 5px 5px !important;  font-size: 7.5px !important;  border: 1px solid #d0d8e4 !important;  text-align: center !important;  white-space: normal !important;  vertical-align: middle !important;  }  .data-table tbody tr:nth-child(even) {  background: #f8fafc !important;  }  .data-table tbody tr { page-break-inside: avoid !important; }  .data-table tfoot td {  padding: 6px !important;  font-size: 8px !important;  border-top: 2px solid #003366 !important;  border: 1px solid #9aafcc !important;  font-weight: 700 !important;  background: #eef2f8 !important;  }  /* Badges */  .badge {  border: 1px solid #999 !important;  padding: 1px 4px !important;  font-size: 6.5px !important;  border-radius: 2px !important;  font-weight: 600 !important;  }  .empty-state { display: none !important; }  /* Page footer */  .rpt-printable::after {  content: 'PETRON STATION MANAGEMENT SYSTEM  |  CONFIDENTIAL  |  Generated: ' attr(data-print-date);  display: block;  font-size: 7px;  color: #718096;  text-align: center;  border-top: 1px solid #cbd5e1;  padding-top: 6px;  margin-top: 20px;  }
