</style>  <div class="report-container">  <!-- Date Filters - Moved to Top -->  <div class="filters-card">  <form method="GET">  <div class="filters-grid">  <div class="form-group">  <label>Date From</label>  <input type="date" class="form-control" name="date_from" value="<?php echo htmlspecialchars($date_from); ?>">  </div>  <div class="form-group">  <label>Date To</label>  <input type="date" class="form-control" name="date_to" value="<?php echo htmlspecialchars($date_to); ?>">  </div>  </div>  <div class="actions-bar">  <div>  <button type="submit" class="btn btn-primary">  <i class="fas fa-filter"></i> Apply Filters  </button>  <a href="?" class="btn btn-secondary">  <i class="fas fa-times"></i> Clear  </a>  </div>  <div class="rpt-export-actions">  <button type="button" class="rpt-export-btn" onclick="window.print()">  <i class="fas fa-print"></i> Print PDF  </button>  <button type="button" class="rpt-export-btn" onclick="exportReport('excel')">  <i class="fas fa-file-excel"></i> Export Excel  </button>  <button type="button" class="rpt-export-btn" onclick="exportReport('csv')">  <i class="fas fa-file-csv"></i> Export CSV  </button>  </div>  </div>  </form>  </div>  <!-- Printable Content: Title + Report Cards -->  <div class="rpt-printable" data-print-date="<?php echo date('F j, Y g:i A'); ?>">  <!-- Page Header - Manager Style (Moved below filters) -->  <div style="text-align:center;padding:22px 0 14px;border-bottom:2px solid #e2e8f0;margin-bottom:20px;">  <div style="font-size:20px;font-weight:800;color:#003366;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px;">  SECURITY REPORTS  </div>  <div style="font-size:12px;color:#64748b;margin-bottom:2px;">  Login Attempts  Access Violations  Password Resets  Suspicious Activity  </div>  <div style="font-size:12px;color:#334155;">  <strong>Date:</strong>  <?php echo date('F j, Y', strtotime($date_from)); ?>  <?php echo $date_from !== $date_to ? ' – ' . date('F j, Y', strtotime($date_to)) : ''; ?>  </div>  </div>  <script>  function exportToCSV() {  const params = new URLSearchParams(window.location.search);  const dateFrom = params.get('date_from') || '<?php echo $date_from; ?>';  const dateTo = params.get('date_to') || '<?php echo $date_to; ?>';  window.location.href = '../backend/api/developer_reports_api.php?action=export_csv&report_type=security&date_from=' + dateFrom + '&date_to=' + dateTo;  }  </script>  <!-- Login Attempts Summary -->  <div class="stats-grid">  <div class="stat-box">  <div class="stat-label">Total Login Attempts</div>  <div class="stat-value" style="color: var(--info-color);">  <?php echo number_format($sec_total_logins); ?>  </div>  </div>  <div class="stat-box">  <div class="stat-label">Successful Logins</div>  <div class="stat-value" style="color: var(--success-color);">  <?php echo number_format($sec_success_logins); ?>  </div>  </div>  <div class="stat-box">  <div class="stat-label">Failed Logins</div>  <div class="stat-value" style="color: var(--danger-color);">  <?php echo number_format($sec_failed_logins); ?>  </div>  </div>  <div class="stat-box">  <div class="stat-label">Access Violations</div>  <div class="stat-value" style="color: var(--warning-color);">  <?php echo number_format(count($access_violations)); ?>  </div>  </div>  <div class="stat-box">  <div class="stat-label">Suspicious Activity</div>  <div class="stat-value" style="color: var(--danger-color);">  <?php echo number_format(count($suspicious_activity)); ?>  </div>  </div>  </div>  <!-- Login Attempts -->  <div class="report-card">  <div class="report-card-header">  <h3 class="report-card-title"><i class="fas fa-sign-in-alt"></i> Login Attempts</h3>  </div>  <div class="report-card-body">  <?php if (empty($login_attempts)): ?>  <div class="empty-state">  <i class="fas fa-sign-in-alt" style="font-size: 3rem; opacity: 0.3;"></i>  <p>No login attempts recorded</p>  </div>  <?php else: ?>  <div style="overflow:hidden;">  <table class="data-table">  <thead>  <tr>  <th>Username / Email</th>  <th>Status</th>  <th>Count</th>  <th>IP Address</th>  <th>Failure Reason</th>  <th>Last Attempt</th>  </tr>  </thead>  <tbody>  <?php foreach ($login_attempts as $attempt): ?>  <tr>  <td><?php echo htmlspecialchars($attempt['username']); ?></td>  <td>  <span class="badge badge-<?php echo $attempt['attempt_type'] === 'success' ? 'success' : 'danger'; ?>">  <?php echo strtoupper($attempt['attempt_type']); ?>  </span>  </td>  <td><?php echo number_format($attempt['attempt_count']); ?></td>  <td><?php echo htmlspecialchars($attempt['ip_address'] ?? 'N/A'); ?></td>  <td style="font-size:0.8rem; color:var(--text-secondary);">  <?php echo htmlspecialchars($attempt['failure_reasons'] ?? '—'); ?>  </td>  <td><?php echo date('Y-m-d H:i:s', strtotime($attempt['last_attempt'])); ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  </div>  <?php endif; ?>  </div>  </div>  <!-- Access Violations -->  <div class="report-card">  <div class="report-card-header">  <h3 class="report-card-title"><i class="fas fa-shield-alt"></i> Access Violations</h3>  </div>  <div class="report-card-body">  <?php if (empty($access_violations)): ?>  <div class="empty-state">  <i class="fas fa-check-circle" style="font-size: 3rem; opacity: 0.3; color: var(--success-color);"></i>  <p>No access violations. System is secure!</p>  </div>  <?php else: ?>  <div style="overflow:hidden;">  <table class="data-table">  <thead>  <tr>  <th>ID</th>  <th>Username</th>  <th>Resource</th>  <th>Violation Type</th>  <th>IP Address</th>  <th>Timestamp</th>  </tr>  </thead>  <tbody>  <?php foreach ($access_violations as $violation): ?>  <tr>  <td><?php echo $violation['id']; ?></td>  <td><?php echo htmlspecialchars($violation['username'] ?? 'Unknown'); ?></td>  <td><?php echo htmlspecialchars($violation['attempted_resource']); ?></td>  <td>  <span class="badge badge-danger">  <?php echo htmlspecialchars($violation['violation_type']); ?>  </span>  </td>  <td><?php echo htmlspecialchars($violation['ip_address'] ?? 'N/A'); ?></td>  <td><?php echo date('Y-m-d H:i:s', strtotime($violation['created_at'])); ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  </div>  <?php endif; ?>  </div>  </div>  <!-- Password Reset Logs -->  <div class="report-card">  <div class="report-card-header">  <h3 class="report-card-title"><i class="fas fa-key"></i> Password Reset Logs</h3>  </div>  <div class="report-card-body">  <?php if (empty($password_resets)): ?>  <div class="empty-state">  <i class="fas fa-key" style="font-size: 3rem; opacity: 0.3;"></i>  <p>No password resets recorded</p>  </div>  <?php else: ?>  <div style="overflow:hidden;">  <table class="data-table">  <thead>  <tr>  <th>ID</th>  <th>Username</th>  <th>Reset Method</th>  <th>Status</th>  <th>IP Address</th>  <th>Requested</th>  <th>Completed</th>  </tr>  </thead>  <tbody>  <?php foreach ($password_resets as $reset): ?>  <tr>  <td><?php echo $reset['id']; ?></td>  <td><?php echo htmlspecialchars($reset['username'] ?? 'N/A'); ?></td>  <td><?php echo htmlspecialchars($reset['reset_method'] ?? 'N/A'); ?></td>  <td>  <span class="badge badge-<?php echo $reset['status'] === 'completed' ? 'success' : 'warning'; ?>">  <?php echo strtoupper($reset['status']); ?>  </span>  </td>  <td><?php echo htmlspecialchars($reset['ip_address'] ?? 'N/A'); ?></td>  <td><?php echo date('Y-m-d H:i:s', strtotime($reset['created_at'])); ?></td>  <td><?php echo $reset['completed_at'] ? date('Y-m-d H:i:s', strtotime($reset['completed_at'])) : 'Pending'; ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  </div>  <?php endif; ?>  </div>  </div>  <!-- Suspicious Activity -->  <div class="report-card">  <div class="report-card-header">  <h3 class="report-card-title"><i class="fas fa-exclamation-triangle"></i> Suspicious Activity Alerts</h3>  </div>  <div class="report-card-body">  <?php if (empty($suspicious_activity)): ?>  <div class="empty-state">  <i class="fas fa-check-circle" style="font-size: 3rem; opacity: 0.3; color: var(--success-color);"></i>  <p>No suspicious activity detected. All clear!</p>  </div>  <?php else: ?>  <div style="overflow:hidden;">  <table class="data-table">  <thead>  <tr>  <th>ID</th>  <th>Username</th>  <th>Activity Type</th>  <th>Severity</th>  <th>Description</th>  <th>IP Address</th>  <th>Status</th>  <th>Detected</th>  </tr>  </thead>  <tbody>  <?php foreach ($suspicious_activity as $activity): ?>  <tr>  <td><?php echo $activity['id']; ?></td>  <td><?php echo htmlspecialchars($activity['username'] ?? 'Unknown'); ?></td>  <td><?php echo htmlspecialchars($activity['activity_type']); ?></td>  <td>  <span class="badge badge-<?php  echo $activity['severity'] === 'high' ? 'danger' :  ($activity['severity'] === 'medium' ? 'warning' : 'info');  ?>">  <?php echo strtoupper($activity['severity']); ?>  </span>  </td>  <td><?php echo htmlspecialchars(substr($activity['description'] ?? '', 0, 50)) . '...'; ?></td>  <td><?php echo htmlspecialchars($activity['ip_address'] ?? 'N/A'); ?></td>  <td>  <span class="badge badge-<?php echo $activity['status'] === 'resolved' ? 'success' : 'danger'; ?>">  <?php echo strtoupper($activity['status']); ?>  </span>  </td>  <td><?php echo date('Y-m-d H:i:s', strtotime($activity['created_at'])); ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  </div>  <?php endif; ?>  </div>  </div>  </div><!-- End .rpt-printable -->
</div>  <script src="../assets/vendor/xlsx/xlsx.full.min.js"></script>
<script>
function exportReport(type) {  if (typeof XLSX === 'undefined') {  alert('Export library not loaded. Please refresh the page and try again.');  return;  }  const tables = Array.from(document.querySelectorAll('.report-card .data-table')).filter(  t => t.querySelector('tbody tr')  );  if (!tables.length) {  alert('No table data found to export.');  return;  }  const dateFrom = document.querySelector('input[name="date_from"]')?.value || '';  const dateTo = document.querySelector('input[name="date_to"]')?.value || '';  const filename = `Security_Report_${dateFrom}_to_${dateTo}`;  if (type === 'csv') {  exportCSV(tables, filename);  } else {  exportExcel(tables, filename);  }
}  function tableToAoA(table) {  const aoa = [];  table.querySelectorAll('thead tr').forEach(tr => {  aoa.push([...tr.querySelectorAll('th')].map(th => th.innerText.trim()));  });  table.querySelectorAll('tbody tr').forEach(tr => {  aoa.push([...tr.querySelectorAll('td')].map(td => td.innerText.trim()));  });  return aoa;
}  function exportExcel(tables, filename) {  const wb = XLSX.utils.book_new();  const usedNames = {};  tables.forEach((tbl, i) => {  const card = tbl.closest('.report-card');  let sheetName = card?.querySelector('.report-card-title')?.innerText?.trim() || `Sheet ${i + 1}`;  sheetName = sheetName.replace(/[:\\\/?*\[\]]/g, '').substring(0, 31).trim() || `Sheet${i+1}`;  if (usedNames[sheetName]) {  usedNames[sheetName]++;  sheetName = (sheetName.substring(0, 28) + ' ' + usedNames[sheetName]).substring(0,31);  } else {  usedNames[sheetName] = 1;  }  const aoa = tableToAoA(tbl);  const ws = XLSX.utils.aoa_to_sheet(aoa);  if (aoa.length && aoa[0]) {  ws['!cols'] = aoa[0].map((_, ci) => ({  wch: Math.min(45, Math.max(10, ...aoa.map(row => String(row[ci] ?? '').length)))  }));  }  XLSX.utils.book_append_sheet(wb, ws, sheetName);  });  XLSX.writeFile(wb, filename + '.xlsx');
}  function exportCSV(tables, filename) {  let csv = '';  tables.forEach((tbl, i) => {  const card = tbl.closest('.report-card');  const heading = card?.querySelector('.report-card-title')?.innerText?.trim();  if (heading) csv += '"' + heading.replace(/"/g, '""') + '"\n';  else if (i > 0) csv += '\n';  tableToAoA(tbl).forEach(row => {  csv += row.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(',') + '\n';  });  csv += '\n';  });  const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });  const url = URL.createObjectURL(blob);  const a = document.createElement('a');  a.href = url;  a.download = filename + '.csv';  document.body.appendChild(a);  a.click();  setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 200);
}
</script>  <?php include __DIR__ . '/../partials/footer.php'; ?>
